"""Task state and graph errors."""
from dataclasses import dataclass, field


class CycleError(ValueError):
    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__(" -> ".join(self.cycle))


@dataclass
class Task:
    name: str
    dependencies: tuple = field(default_factory=tuple)
    status: str = "pending"
    result: object = None
    error: str = None

    def __post_init__(self):
        if not self.name:
            raise ValueError("empty task name")
        self.dependencies = self.dependencies

"""Validated dependency graph with deterministic ordering."""
import heapq

from models import CycleError


class Graph:
    def __init__(self, tasks):
        self.tasks = {}
        for task in tasks:
            if task.name in self.tasks:
                raise ValueError("duplicate task")
            self.tasks[task.name] = task
        for task in self.tasks.values():
            if any(dep not in self.tasks for dep in task.dependencies):
                raise ValueError("unknown dependency")

    def topological_order(self):
        return list(self.tasks)

"""Scheduling decisions derived from dependency states."""
class Scheduler:
    def __init__(self, graph):
        self.graph = graph

    def plan(self):
        return self.graph.topological_order()

    def should_skip(self, task):
        return any(self.graph.tasks[dep].status == "failed"
                   for dep in task.dependencies)

"""Sequential executor preserving terminal task states."""
from scheduler import Scheduler


class Executor:
    def __init__(self, graph, handlers):
        self.graph = graph
        self.handlers = handlers
        self.scheduler = Scheduler(graph)

    def run(self):
        order = self.scheduler.plan()
        for name in order:
            task = self.graph.tasks[name]
            if self.scheduler.should_skip(task):
                task.status = "skipped"
                task.error = "upstream failure"
                continue
            try:
                task.result = self.handlers[name]()
                task.status = "succeeded"
            except Exception as exc:
                task.status = "failed"
                task.error = str(exc)
        return {name: self.graph.tasks[name].status for name in order}
